const item = $input.first().json;
const raw = String(item.chatInput ?? item.message ?? '');
// bare draft number -> schedule (takes priority over keyword routing)
const isBareNumber = /^\s*\d+\s*$/.test(raw);

const stripped = raw
  .replace(/change\s+(the\s+)?(publishing\s+)?(date|time|schedule)/ig, ' ')
  .replace(/publishing\s+time/ig, ' ');

const isWrite = /(rewrite|rephrase|revise|\bedit\b|shorter|longer|hashtag|\btone\b|wording|\bcontent\b|make it|\bwrite\b|create (a )?post|new post|hook|typo|emoji|about )/i.test(stripped);
const isSchedule = /(reschedule|schedule|publishing time|publish\b|\bapprov|\blooks good\b|\bgo ahead\b|ship it|move (it )?to|postpone|delay|change\s+(the\s+)?(publishing\s+)?(date|time|schedule)|\b\d{1,2}(:\d{2})?\s*(am|pm)\b|tomorrow|tonight|next (monday|tuesday|wednesday|thursday|friday|saturday|sunday))/i.test(raw);
const isAdmin = /(show|list|get draft|get post|status|when is|what time|at what time|what('s| is)|find draft|lookup|retrieve|draft id|post id|\bid\s*\d+|scheduled_at|supposed to|when .+ publish|publish(?:ed)? (?:at|on|time))/i.test(raw);

let route = 'write';
if (isBareNumber) route = 'schedule';
else if (isWrite && isSchedule) route = 'write_and_schedule';
else if (isSchedule && !isWrite) route = 'schedule';
else if (isAdmin && !isWrite) route = 'admin';

return [{
  json: {
    ...item,
    route,
    chatInput: item.chatInput ?? raw,
    sessionId: item.sessionId,
  },
}];

